<script setup lang="ts">import{ref}from'vue';const saved=ref(false);const siteName=ref('启程校招');const supportEmail=ref('support@example.com');const defaultSeason=ref('2027 届秋招');function save(){saved.value=true;setTimeout(()=>saved.value=false,1800)}</script>
<template><section><header class="admin-page-head"><div><h1>系统配置</h1><p>配置站点展示信息与默认招聘批次。</p></div></header><form class="settings admin-panel" @submit.prevent="save"><label>站点名称<input v-model="siteName"/></label><label>支持邮箱<input v-model="supportEmail" type="email"/></label><label>默认招聘批次<select v-model="defaultSeason"><option>2027 届秋招</option><option>2027 届提前批</option></select></label><label class="switch"><input type="checkbox" checked/>职位截止前 3 天自动创建提醒</label><button class="cl-primary-button">保存配置</button><span v-if="saved" role="status">已保存</span></form></section></template><style scoped>.settings{max-width:650px;display:grid;gap:17px}.settings label:not(.switch){display:grid;gap:6px;font-weight:700}.settings input,.settings select{height:42px;padding:0 11px;border:1px solid var(--cl-border);border-radius:8px;background:var(--cl-canvas)}.switch{display:flex;gap:9px}.settings button{justify-self:start}.settings>span{color:var(--cl-success)}</style>
